    {
        "name": "纨",
        "category": "动物纤维·丝",
        "dynasty_peak": "战国—汉",
        "raw_material": "桑蚕丝（极细）",
        "description": "缫丝极细、织造极密之细绢，色白质密、皎洁如霜雪，为汉代最高级平纹丝织之一。\"齐纨\"（齐国所产）名闻天下，班婕妤《怨歌行》\"新裂齐纨素，皎洁如霜雪\"即咏其洁白；\"纨绔\"本指富贵子弟所着之细绢裤，后成其词源。",
        "source_ref": "《怨歌行》",
        "process": "① 缫丝 → ② 络丝 → ③ 整经 → ④ 平纹细织 → ⑤ 练染 → ⑥ 成衣/扇面",
        "process_steps": [{"title": "① 缫丝", "desc": "煮茧抽丝，纨须取极细之茧丝、少合股缫制，丝缕纤细均匀，为织密细绢之本。"}, {"title": "② 络丝", "desc": "细丝经络丝理直、去糙，绕框备用；纨之细腻，自络丝起即须惜丝。"}, {"title": "③ 整经", "desc": "整经时大幅提高经密，经纬细密排布，为织皎洁密实之绢面做准备。"}, {"title": "④ 平纹细织", "desc": "平纹织造而经纬极密，打纬密实，布面平整细密、几不见孔隙。织成之纨色白质密，皎洁如霜雪。"}, {"title": "⑤ 练染", "desc": "练丝去胶增白，纨多保持素白（\"纨素\"），亦可染成彩色。"}, {"title": "⑥ 成衣/扇面", "desc": "纨可制衣（纨衣、纨裤）、巾帕，亦大量用作纨扇扇面（\"团扇\"）。班婕妤\"新裂齐纨素，皎洁如霜雪。裁为合欢扇，团团似明月\"，即咏纨与纨扇。"}],
        "poems": [{"text": "① 汉·班婕妤《怨歌行》：\"新裂齐纨素，皎洁如霜雪。裁为合欢扇，团团似明月。\"", "src": "《怨歌行》", "url": "https://www.baidu.com/s?wd=怨歌行+新裂齐纨素"}, {"text": "② 汉·许慎《说文解字》：\"纨，素也。\"", "src": "《说文解字》", "url": "https://www.baidu.com/s?wd=说文解字+纨+素也"}, {"text": "③ 汉·《释名·释采帛》：\"纨，焕也，细泽有光焕焕然也。\"（概引）", "src": "《释名·释采帛》", "url": "https://www.baidu.com/s?wd=释名+纨+焕也"}, {"text": "④ 《汉书》载\"齐纨鲁缟\"之语（山东丝织并称，概引）。", "src": "《汉书》", "url": "https://www.baidu.com/s?wd=齐纨鲁缟+汉书"}],
    },
